</section><script>
(()=>{const RM=matchMedia("(prefers-reduced-motion: reduce)").matches;
const vis=e=>e&&e.offsetParent!==null;
const drag=()=>document.querySelectorAll(".sodz").forEach(z=>{const d=z.querySelector(".sodrag"),s=z.querySelector(".sosrc"),t=z.querySelector(".sotgt");if(!d||!s||!t||!z.offsetWidth)return;const Z=z.getBoundingClientRect(),S=s.getBoundingClientRect(),T=t.getBoundingClientRect();const v={"--fx":S.left-Z.left,"--fy":S.top-Z.top,"--tx":T.left-Z.left,"--ty":T.top-Z.top,"--sw":S.width,"--tw":T.width};for(const k in v)d.style.setProperty(k,v[k].toFixed(1)+"px")});
const ptr=z=>{const p=z.querySelector(":scope>.sopt");if(!p||RM||!z.offsetWidth)return;const D=+z.dataset.d||8,R=z.getBoundingClientRect();
const pts=z.dataset.p.split(",").map(x=>{const [sel,pc]=x.split("@");const e=z.querySelector(sel);if(!e)return null;const r=e.getBoundingClientRect();return[r.left-R.left+r.width*.5,r.top-R.top+r.height*.55,+pc]}).filter(Boolean);if(!pts.length)return;
const id="sop"+Math.round(R.width)+"x"+Math.round(R.height)+"x"+pts.map(q=>Math.round(q[0])+"_"+Math.round(q[1])).join("_");if(p.dataset.k===id)return;p.dataset.k=id;
const S=[R.width*.92,R.height+12],T=(q,s)=>`transform:translate(${q[0].toFixed(1)}px,${q[1].toFixed(1)}px)${s?" scale("+s+")":""}`;
let k=`0%{${T(S)};opacity:0}`,prev=0;
pts.forEach((q,i)=>{const a=q[2];if(i===0)k+=`${Math.max(3,a-20)}%{${T(S)};opacity:1}`;else{const h=Math.max(prev+4,a-14);if(h>prev)k+=`${h}%{${T(pts[i-1])}}`}k+=`${a}%{${T(q)}}${a+1}%{${T(q,.8)}}${a+2.5}%{${T(q)}}`;prev=a+2.5});
const L=pts[pts.length-1];k+=`${Math.min(prev+8,88)}%{${T(L)};opacity:1}${Math.min(prev+18,96)}%{${T(S)};opacity:0}100%{${T(S)};opacity:0}`;
let st=z.querySelector(":scope>style.sopk");if(!st){st=document.createElement("style");st.className="sopk";z.appendChild(st)}st.textContent=`@keyframes ${id}{${k}}`;p.style.animation=`${id} ${D}s cubic-bezier(.45,0,.2,1) infinite`};
const fit=()=>{drag();document.querySelectorAll(".sopz[data-p]").forEach(ptr)};
const typer=w=>{const el=w.querySelector(".soty[data-t]");if(!el)return;const t=el.dataset.t,cc=w.querySelector(".socc"),sp=t.length<24?110:42;w.classList.add("js");if(RM){w.classList.add("done");return}let i=0;el.textContent="";
const tick=()=>{if(!vis(el)){i=0;el.textContent="";w.classList.remove("done");return setTimeout(tick,600)}if(i<=t.length){el.textContent=t.slice(0,i);if(cc)cc.textContent=i;i++;if(i>t.length){w.classList.add("done");setTimeout(tick,3800)}else setTimeout(tick,sp+Math.random()*sp)}else{i=0;el.textContent="";if(cc)cc.textContent=0;w.classList.remove("done");setTimeout(tick,800)}};setTimeout(tick,900)};
const typer2=el=>{const t=el.dataset.t;if(RM)return;let i=0;el.textContent="";const tick=()=>{if(!vis(el)){i=0;el.textContent="";return setTimeout(tick,700)}if(i<=t.length){el.textContent=t.slice(0,i);i++;setTimeout(tick,i>t.length?2800:75)}else{i=0;el.textContent="";setTimeout(tick,900)}};setTimeout(tick,2600)};
const fmt=(n,k)=>k?(n/1000).toFixed(1)+"K":Math.round(n).toLocaleString("en");
const cnt=e=>{const a=+e.dataset.a,b=+e.dataset.b,k=e.dataset.k,w=+e.dataset.w||300;e.textContent=fmt(b,k);if(RM)return;let was=false;setInterval(()=>{const v=vis(e);if(v&&!was){const t0=performance.now()+w;e.textContent=fmt(a,k);const f=now=>{const p=Math.min(1,Math.max(0,(now-t0)/1300));e.textContent=fmt(a+(b-a)*(1-Math.pow(1-p,3)),k);if(p<1)requestAnimationFrame(f)};requestAnimationFrame(f)}was=v},250)};
const tc=()=>document.querySelectorAll(".sotl").forEach(l=>{const h=l.querySelector(".sotlh"),c=l.querySelector(".sotc");if(!h||!c)return;if(RM){c.textContent="0:15";return}if(!vis(h))return;const a=h.getAnimations()[0];if(!a)return;const s=Math.floor(((a.currentTime||0)%6000)/6000*16);c.textContent="0:"+String(Math.min(s,15)).padStart(2,"0")});
document.addEventListener("DOMContentLoaded",()=>{fit();document.querySelectorAll(".sotyw").forEach(typer);document.querySelectorAll(".soty2[data-t]").forEach(typer2);document.querySelectorAll(".socnt").forEach(cnt);tc();setInterval(tc,200)});
addEventListener("load",fit);addEventListener("resize",fit);document.addEventListener("click",()=>setTimeout(fit,60));document.addEventListener("input",()=>setTimeout(fit,60));
if(document.fonts)document.fonts.ready.then(fit)})();
</script>
